{"01-header.html": "<style>
#top {
  background:#fffaf0;
  color:#1b3a2a;
  padding:1rem 1.25rem;
  font-family: Georgia, 'Times New Roman', serif;
}
#top .brand {
  font-size:1.75rem;
  font-weight:700;
  letter-spacing:0.02em;
  color:#1b3a2a;
  text-decoration:none;
}
#top .brand span {
  color:#b45309;
}
#top nav {
  margin-top:0.75rem;
}
#top nav ul {
  list-style:none;
  margin:0;
  padding:0;
  display:flex;
  flex-wrap:wrap;
  gap:1rem 1.5rem;
}
#top nav a {
  color:#1b3a2a;
  text-decoration:none;
  font-weight:600;
  padding:0.25rem 0.5rem;
  border-bottom:2px solid transparent;
}
#top nav a:hover,
#top nav a:focus {
  border-bottom-color:#b45309;
  outline:none;
}
#top .container {
  max-width:1200px;
  margin:0 auto;
}
@media (max-width:600px){
  #top nav ul {
    flex-direction:column;
    gap:0.5rem;
  }
}
</style>
<header id="top">
  <div class="container">
    <a href="#top" class="brand">Common Ground<span> Coffee</span></a>
    <nav aria-label="Primary">
      <ul>
        <li><a href="#menu">Menu</a></li>
        <li><a href="#mission">Mission</a></li>
        <li><a href="#events">Events</a></li>
        <li><a href="#visit">Visit</a></li>
      </ul>
    </nav>
  </div>
</header>
", "02-hero.html": "<section id="hero">
<style>
#hero{--cream:#fff8ec;--forest:#1e3a2a;--copper:#b86a3a;--ink:#2b2b2b;position:relative;isolation:isolate;background:var(--cream);color:var(--ink);padding:96px 20px 120px;text-align:center;font-family:system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif}
#hero::before{content:"";position:absolute;inset:0;background:radial-gradient(1200px 600px at 50% -10%, #f3e6d2 0%, transparent 60%),linear-gradient(180deg, rgba(255,255,255,.6), transparent);pointer-events:none;z-index:0}
#hero .hero-inner{position:relative;z-index:1;max-width:1100px;margin:0 auto}
#hero h1{font-weight:800;letter-spacing:-0.02em;line-height:1.05;margin:0 0 18px;font-size:clamp(40px,6vw,72px);color:var(--forest)}
#hero .tagline{font-size:clamp(16px,2.2vw,20px);margin:0 auto 32px;max-width:720px;color:#3a3a3a}
#hero .cta-row{display:flex;gap:16px;justify-content:center;flex-wrap:wrap;margin-top:28px}
#hero .cta{appearance:none;border:2px solid var(--forest);background:var(--forest);color:#fff;padding:14px 28px;font-size:18px;font-weight:600;border-radius:10px;text-decoration:none;display:inline-block;transition:transform .08s ease}
#hero .cta.secondary{background:transparent;color:var(--forest)}
#hero .cta:hover{transform:translateY(-2px)}
#hero .visual{margin:48px auto 0;max-width:900px;height:260px;position:relative}
#hero .cup{width:220px;height:220px;margin:0 auto;position:relative;z-index:1}
#hero .cup svg{display:block;width:100%;height:auto}
@media (max-width:600px){#hero{padding:72px 16px 100px}#hero h1{font-size:clamp(28px,9vw,48px)}#hero .cta{padding:12px 22px;font-size:17px}#hero .visual{height:200px}}
</style>
<div class="hero-inner">
<h1>Excellent coffee funding opportunity</h1>
<p class="tagline">Common Ground Coffee is a nonprofit cafe in Palo Alto where every cup supports job training and community meals.</p>
<div class="cta-row">
<a class="cta" href="#menu">Explore the menu</a>
<a class="cta secondary" href="#mission">Our mission</a>
</div>
<div class="visual" aria-hidden="true">
<div class="cup">
<svg viewBox="0 0 200 200" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Coffee cup illustration">
<defs>
<linearGradient id="g" x1="0" y1="0" x2="0" y2="1">
<stop offset="0%" stop-color="#d9c4a8"/>
<stop offset="100%" stop-color="#bfa07a"/>
</defs>
<ellipse cx="100" cy="170" rx="70" ry="12" fill="rgba(0,0,0,.08)"/>
<rect x="40" y="60" width="120" height="100" rx="28" fill="url(#g)" stroke="#8c6a4a" stroke-width="4"/>
<rect x="40" y="60" width="120" height="100" rx="28" fill="none" stroke="rgba(0,0,0,.06)" stroke-width="2"/>
<rect x="150" y="80" width="18" height="60" rx="9" fill="url(#g)" stroke="#8c6a4a" stroke-width="4"/>
<path d="M60 110 Q100 85 140 110" fill="none" stroke="#3a2a1a" stroke-width="6" stroke-linecap="round" opacity=".25"/>
</svg>
</div>
</div>
</div>
</section>
", "03-mission.html": "<style>
#mission {
  --cream: #fff8ec;
  --forest: #1e3a2a;
  --copper: #b86a3a;
  background: var(--cream);
  color: var(--forest);
  padding: 72px 24px;
  font-family: system-ui, -apple-system, Segoe UI, Roboto, sans-serif;
}
#mission h2 {
  font-size: clamp(28px, 4vw, 40px);
  line-height: 1.2;
  margin: 0 0 20px;
  color: var(--forest);
}
#mission .mission-card {
  max-width: 760px;
  margin: 0 auto;
  background: #ffffff;
  border: 1px solid #e6dccb;
  border-radius: 16px;
  padding: 28px 32px;
  box-shadow: 0 6px 18px rgba(30,58,42,0.06);
}
#mission p {
  font-size: 18px;
  line-height: 1.7;
  margin: 0 0 16px;
}
#mission .highlight {
  color: var(--copper);
  font-weight: 700;
}
#mission .tag {
  display: inline-block;
  background: var(--forest);
  color: #fff;
  font-size: 13px;
  letter-spacing: .04em;
  text-transform: uppercase;
  padding: 6px 10px;
  border-radius: 999px;
  margin-bottom: 14px;
}
@media (max-width: 480px) {
  #mission { padding: 48px 16px; }
  #mission .mission-card { padding: 20px 20px; }
}
</style>
<section id="mission">
  <div class="mission-card">
    <span class="tag">Nonprofit</span>
    <h2>Our mission</h2>
    <p>Common Ground Coffee is a <strong>nonprofit</strong> cafe rooted in Palo Alto. We believe great coffee can build lasting community.</p>
    <p>We operate as a <strong>nonprofit</strong> and commit that <strong>100% of surplus funds</strong> support job training for neighbors seeking pathways into hospitality careers. Every cup helps fund hands-on learning, mentorship, and paid work experience.</p>
    <p>With warmth, dignity, and care, we create a welcoming space where people gather, learn, and grow together.</p>
  </div>
</section>
", "04-menu.html": "<style>
#menu {
  --cream:#fff8ec;
  --forest:#1e3a2a;
  --copper:#b86a3a;
  background: var(--cream);
  color: var(--forest);
  padding: 64px 20px;
  font-family: system-ui, -apple-system, Segoe UI, Roboto, sans-serif;
}
#menu h2 {
  font-size: clamp(28px, 4vw, 40px);
  margin: 0 0 24px;
  letter-spacing: .2px;
}
#menu .search-wrap {
  margin-bottom: 28px;
}
#menu label[for="menu-search"] {
  font-weight: 600;
  margin-right: 8px;
}
#menu #menu-search {
  font-size: 16px;
  padding: 10px 12px;
  border: 2px solid #d9c9b3;
  border-radius: 8px;
  width: min(420px, 100%);
  background: white;
}
#menu .menu-grid {
  display: grid;
  gap: 20px;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
}
#menu .card {
  background: white;
  border: 1px solid #e6dccb;
  border-radius: 12px;
  padding: 20px;
  box-shadow: 0 2px 6px rgba(0,0,0,.04);
}
#menu .card .name {
  font-weight: 700;
  font-size: 20px;
  margin: 0 0 6px;
}
#menu .card .price {
  color: var(--copper);
  font-weight: 600;
}
#menu #menu-empty {
  margin-top: 24px;
  font-style: italic;
  color: #5a4a3a;
}
</style>
<section id="menu">
  <h2>Our menu</h2>
  <div class="search-wrap">
    <label for="menu-search">Search drinks</label>
    <input id="menu-search" type="search" placeholder="Search drinks" aria-label="Search menu items">
  </div>
  <div class="menu-grid">
    <div class="card" data-menu-item data-name="Espresso">
      <p class="name">Espresso</p>
      <p class="price">$3</p>
    </div>
    <div class="card" data-menu-item data-name="Oat Latte">
      <p class="name">Oat Latte</p>
      <p class="price">$5</p>
    </div>
    <div class="card" data-menu-item data-name="Cold Brew">
      <p class="name">Cold Brew</p>
      <p class="price">$4</p>
    </div>
  </div>
  <p id="menu-empty" hidden>No drinks found. Try a different search.</p>
</section>
", "05-impact.html": "<section id="impact">
<style>
#impact {
  --cream:#fff8ec;
  --forest:#1e3a2a;
  --copper:#b86a3a;
  background: var(--cream);
  color: var(--forest);
  padding: 64px 20px;
  font-family: system-ui, -apple-system, Segoe UI, Roboto, sans-serif;
}
#impact h2 {
  font-size: clamp(28px, 4vw, 40px);
  margin: 0 0 32px;
  text-align: center;
  letter-spacing: .2px;
}
#impact .stats {
  display: grid;
  gap: 24px;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  max-width: 1100px;
  margin: 0 auto;
}
#impact .stat {
  background: #fff;
  border: 1px solid #e6dccb;
  border-top: 4px solid var(--copper);
  border-radius: 12px;
  padding: 28px 20px;
  text-align: center;
  box-shadow: 0 2px 6px rgba(0,0,0,.04);
}
#impact .stat .number {
  font-size: clamp(36px, 6vw, 48px);
  font-weight: 700;
  line-height: 1.1;
  color: var(--forest);
}
#impact .stat .label {
  margin-top: 8px;
  font-size: 16px;
  color: #3a4a3f;
}
#impact .intro {
  text-align: center;
  max-width: 720px;
  margin: 0 auto 40px;
  font-size: 18px;
  line-height: 1.6;
}
@media (max-width: 480px){
  #impact { padding: 48px 16px; }
  #impact .stat { padding: 22px 16px; }
}
</style>
<h2>Our Impact</h2>
<p class="intro">Every cup supports neighbors in Palo Alto. This year our nonprofit cafe turned coffee into opportunity.</p>
<div class="stats">
  <div class="stat">
    <div class="number">2,500</div>
    <div class="label">Community meals served annually</div>
  </div>
  <div class="stat">
    <div class="number">120</div>
    <div class="label">Training hours provided annually</div>
  </div>
  <div class="stat">
    <div class="number">35</div>
    <div class="label">Graduates placed in jobs annually</div>
  </div>
</div>
</section>
", "06-events.html": "<section id="events">
<style>
#events{font-family:system-ui,-apple-system,Segoe UI,Roboto,sans-serif;color:#1f2a1a;background:#fffdf6;padding:64px 20px}
#events h2{font-size:clamp(28px,4vw,40px);margin:0 0 28px;color:#1b3a2a;letter-spacing:.2px}
#events .events-grid{display:grid;gap:20px;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));align-items:start}
#events .event-card{background:#fff;border:1px solid #e6e2d6;border-radius:12px;padding:20px;box-shadow:0 2px 8px rgba(0,0,0,.04);position:relative;overflow:hidden}
#events .event-card::before{content:"";position:absolute;inset:0;background:radial-gradient(120% 80% at 0% 0%,rgba(184,115,60,.08),transparent 60%);pointer-events:none}
#events .event-card h3{margin:0 0 8px;font-size:22px;color:#1b3a2a}
#events time{display:block;font-weight:600;color:#7a4a2a;margin-bottom:10px}
#events .event-card p{margin:8px 0 16px;color:#3a3a3a;line-height:1.5}
#events .signup{inline-size:max-content;display:inline-block;padding:10px 16px;background:#1b3a2a;color:#fffdf6;border-radius:8px;text-decoration:none;font-weight:600}
#events .signup:hover{background:#0f241a}
@media (max-width:480px){#events{padding:48px 16px}#events .event-card{padding:16px}}
</style>
<h2>Events</h2>
<div class="events-grid">
<article class="event-card" data-event>
<h3>Community Table</h3>
<time datetime="2027-03-20">Saturday, March 20, 2027 • 6:00 PM</time>
<p>Share a family-style dinner and conversation with neighbors. All are welcome at our communal table.</p>
<a class="signup" href="#newsletter">Sign up</a>
</article>
<article class="event-card" data-event>
<h3>Open Mic</h3>
<time datetime="2027-04-03">Saturday, April 3, 2027 • 7:00 PM</time>
<p>Local poets, musicians, and storytellers take the stage. Sign up to perform or just listen.</p>
<a class="signup" href="#newsletter">Sign up</a>
</article>
<article class="event-card" data-event>
<h3>Coffee Skills</h3>
<time datetime="2027-04-17">Saturday, April 17, 2027 • 10:00 AM</time>
<p>Hands-on workshop on brewing, latte art, and coffee sourcing with our trainers.</p>
<a class="signup" href="#newsletter">Sign up</a>
</article>
</div>
</section>
", "07-visit.html": "<section id="visit">
<style>
#visit{font-family:system-ui,-apple-system,Segoe UI,Roboto,sans-serif;color:#1f2a1a;background:#fffdf6;padding:64px 20px}
#visit h2{font-size:clamp(28px,4vw,40px);line-height:1.1;margin:0 0 24px;color:#1b2e1a}
#visit .visit-wrap{max-width:1100px;margin:0 auto;display:grid;grid-template-columns:1.1fr 0.9fr;gap:40px;align-items:start}
#visit address{font-style:normal;background:#f6f1e3;border:1px solid #e3dcc7;border-radius:12px;padding:24px}
#visit address .name{font-weight:700;font-size:18px;margin-bottom:8px;color:#1b2e1a}
#visit address .street{margin:4px 0}
#visit .hours{margin-top:20px}
#visit .hours h3{margin:0 0 8px;font-size:16px;color:#3a4a2e}
#visit .hours dl{display:grid;grid-template-columns:auto 1fr;gap:6px 12px;font-size:15px}
#visit .hours dt{font-weight:600}
#visit .contact{margin-top:16px;font-size:14px}
#visit .contact a{color:#8b5a2b;text-decoration:none}
#visit .map{position:relative;background:#e9e3d2;border-radius:12px;overflow:hidden;min-height:260px}
#visit .map svg{width:100%;height:100%;display:block}
#visit .map .pin{position:absolute;left:58%;top:42%;transform:translate(-50%,-50%)}
#visit .map .pin-dot{fill:#8b5a2b}
@media (max-width:800px){
#visit .visit-wrap{grid-template-columns:1fr;gap:24px}
#visit{padding:48px 16px}
}
</style>
<h2>Visit us</h2>
<div class="visit-wrap">
<address>
<div class="name">Common Ground Coffee</div>
<div class="street">42 Willow Street</div>
<div class="street">Palo Alto, CA</div>
<div class="hours">
<h3>Hours</h3>
<dl>
<dt>Weekdays</dt><dd>07:00–18:00</dd>
<dt>Weekends</dt><dd>08:00–16:00</dd>
</dl>
</div>
<div class="contact">Email: <a href="mailto:hello@commonground.example">hello@commonground.example</a></div>
</address>
<div class="map" aria-hidden="true">
<svg viewBox="0 0 400 260" xmlns="http://www.w3.org/2000/svg">
<rect width="400" height="260" fill="#e9e3d2"/>
<path d="M0 140 Q100 120 200 140 T400 140" stroke="#c9bfae" stroke-width="8" fill="none"/>
<path d="M80 260 L80 80" stroke="#c9bfae" stroke-width="8" fill="none"/>
<circle cx="240" cy="110" r="6" fill="#8b5a2b"/>
<text x="200" y="50" font-size="14" fill="#3a4a2e">Willow St</text>
</svg>
<div class="pin">
<svg width="28" height="28" viewBox="0 0 24 24">
<circle cx="12" cy="12" r="8" fill="#8b5a2b"/>
<circle cx="12" cy="12" r="3" fill="#fffdf6"/>
</svg>
</div>
</div>
</div>
</section>
", "08-footer.html": "<style>
#newsletter, footer {
  font-family: system-ui, -apple-system, Segoe UI, Roboto, sans-serif;
  color: #1f2a1a;
  background: #fffaf0;
}
#newsletter {
  padding: 64px 20px;
  max-width: 1100px;
  margin: 0 auto;
}
#newsletter h2 {
  font-size: 36px;
  line-height: 1.1;
  margin: 0 0 12px;
  color: #1b2e1a;
}
#newsletter p.lead {
  margin: 0 0 24px;
  font-size: 18px;
  color: #3a4a32;
}
#newsletter-form {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  align-items: flex-end;
}
#newsletter label {
  font-weight: 600;
  font-size: 14px;
  color: #2a3a24;
  width: 100%;
}
#newsletter input[type="email"] {
  flex: 1 1 260px;
  padding: 12px 14px;
  font-size: 16px;
  border: 2px solid #c9b48a;
  border-radius: 8px;
  background: #fff;
}
#newsletter button[type="submit"] {
  padding: 12px 20px;
  font-size: 16px;
  font-weight: 700;
  background: #b45309;
  color: #fffaf0;
  border: none;
  border-radius: 8px;
  cursor: pointer;
}
#newsletter button[type="submit"]:hover {
  background: #92400e;
}
#newsletter-status {
  width: 100%;
  margin-top: 12px;
  font-size: 14px;
  color: #1b2e1a;
}
#newsletter .privacy {
  font-size: 13px;
  color: #5a6a52;
  margin-top: 10px;
}
#newsletter .nonprofit {
  font-size: 14px;
  color: #2a3a24;
  margin-top: 8px;
}
footer {
  padding: 32px 20px;
  text-align: center;
  border-top: 1px solid #e6dcc8;
}
footer .brand {
  font-weight: 800;
  font-size: 20px;
  color: #1b2e1a;
  margin-bottom: 8px;
}
footer nav a {
  color: #1b2e1a;
  text-decoration: none;
  margin: 0 10px;
  font-size: 14px;
}
footer nav a:hover {
  text-decoration: underline;
}
@media (max-width: 480px) {
  #newsletter h2 { font-size: 28px; }
  #newsletter-form { flex-direction: column; align-items: stretch; }
}
</style>
<section id="newsletter">
  <h2>Stay connected</h2>
  <p class="lead">Get updates on community meals, training hours, and new brews.</p>
  <form id="newsletter-form">
    <label for="email">Email address</label>
    <input id="email" type="email" required placeholder="you@example.com" aria-describedby="newsletter-help">
    <button type="submit">Sign up</button>
    <p id="newsletter-status" role="status" aria-live="polite"></p>
    <p id="newsletter-help" class="privacy">We respect your privacy. No spam, unsubscribe anytime. Common Ground Coffee is a nonprofit.</p>
    <p class="nonprofit">Common Ground Coffee is a 501(c)(3) nonprofit. 100% of surplus funds support job training.</p>
  </form>
</section>
<footer>
  <div class="brand">Common Ground Coffee</div>
  <nav aria-label="Footer">
    <a href="#top">Home</a>
    <a href="#menu">Menu</a>
    <a href="#mission">Mission</a>
    <a href="#events">Events</a>
    <a href="#visit">Visit</a>
  </nav>
  <p style="font-size:12px;color:#6a7a60;margin-top:12px;">© Common Ground Coffee, Palo Alto</p>
</footer>
"}

